import{_ as e,o as n,c as s,a4 as l}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"第八部分 · 计算机组成原理","description":"","frontmatter":{},"headers":[],"relativePath":"computer-arch/index.md","filePath":"computer-arch/README.md","lastUpdated":1788475713000}'),r={name:"computer-arch/index.md"};function i(p,a,o,t,c,h){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="第八部分-·-计算机组成原理" tabindex="-1">第八部分 · 计算机组成原理 <a class="header-anchor" href="#第八部分-·-计算机组成原理" aria-label="Permalink to &quot;第八部分 · 计算机组成原理&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><strong>计算机组成原理</strong> 是软件工程师的第二语言——理解 CPU 流水线、缓存一致性协议、GPU SM/warp、HBM、NVLink、TPU 脉动阵列之后，你写的代码才能真正&quot;touch metal&quot;。所有第一部分到第七部分的高层抽象最终都 bind 到硬件：B+ tree 的 page 大小 16KB 是因为 x86 页表粒度为 4KB、SSD 擦除块是 16KB；LSM-tree 的 compaction 必须考虑 DRAM 带宽和 SSD 写入放大；分布式系统的 fsync 延迟上限取决于 NVMe 控制器 NAND 写延迟。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[SQL Query]</span></span>
<span class="line"><span>  └─&gt; B+ tree index lookup → 2-3 level page read</span></span>
<span class="line"><span>      └─&gt; OS page cache / shared_buffers check</span></span>
<span class="line"><span>           └─&gt; If miss: NVMe SSD read → NAND flash read</span></span>
<span class="line"><span>                 └─&gt; SSD controller → PHY → PCIe lane → CPU cache</span></span>
<span class="line"><span>                      └─&gt; CPU L1 cache hit (1ns) → compute result</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Training loop: GPT model]</span></span>
<span class="line"><span>  └─&gt; NVIDIA H100: matmul on Tensor Core (989 TFLOPS FP8)</span></span>
<span class="line"><span>       └─&gt; Warp scheduler: 32 threads / warp, 64 warps / SM</span></span>
<span class="line"><span>            └─&gt; Shared memory async copy (TMA unit) from HBM</span></span>
<span class="line"><span>                 └─&gt; NVLink → NVSwitch → 8-GPU node</span></span>
<span class="line"><span>                      └─&gt; InfiniBand/RoCE → 10K GPU cluster</span></span></code></pre></div><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ul><li><a href="./cpu-pipeline">CPU 流水线与指令级并行</a> — 5-stage pipeline / hazards / forwarding / branch prediction</li><li><a href="./cpu-superscalar">超标量 / OoO / Tomasulo</a> — 多发射 / 记分板 / Tomasulo / ROB / 寄存器重命名</li><li><a href="./memory-hierarchy">存储层次：Cache / DRAM / HBM</a> — L1/L2/L3 / 替换策略 / MESI / DRAM 时序 / HBM3</li><li><a href="./mmu-dma">MMU / TLB / DMA / IOMMU</a> — 虚拟内存硬件、TLB 结构、IOMMU / SMMU、DMA 引擎</li><li><a href="./gpu-architecture">GPU 架构：SM / CUDA Core / Tensor Core</a> — SIMT / warp / 共享内存 / Tensor Core 内部</li><li><a href="./ai-accelerators">AI 加速器：TPU / NPU / FPGA</a> — 脉动阵列 / 数据流架构 / FPGA 推理 / Cerebras/Groq</li><li><a href="./interconnects">总线与互联：PCIe / CXL / NVLink / RDMA</a> — PCIe 拓扑、CXL.mem/cache、NVSwitch、InfiniBand</li><li><a href="./ssd-storage">存储硬件：NAND / SSD FTL / 写入放大 / NVMe</a> — SLC-TLC/QLC、磨损均衡、GC、TRIM、OP、队列模型</li><li><a href="./isa-design">指令集架构：x86 / ARM / RISC-V</a> — RISC vs CISC、SIMD 扩展、微码、解码器</li></ul><p>读完应能回答:</p><ol><li>为什么 C 代码 <code>int sum = a + b</code> 在 CPU 上要经过&quot;取指→译码→执行→访存→写回&quot; 5 阶段</li><li>Zen 5 vs Golden Cove vs Apple M3 微架构的核心差异（解码器宽度、ROB 大小、执行端口数）</li><li>L1 cache 为什么只有 32-64KB？为什么 L2 要大？为什么 MESI 协议需要 4 种状态？</li><li>Tensor Core 一个 cycle 做 4×4 FP16 FMA 意味着什么？为什么 HBM3 带宽是 3.35 TB/s 但 GPU 算力是 989 TFLOPS？</li><li>CUDA warp 为什么是 32 个线程？divergent branch 的代价是什么？</li><li>NVLink 5 为什么是 900 GB/s per GPU？NVSwitch 如何让 8 GPU 全互联？</li><li>x86 的 <code>rep movsb</code> 和 ARM SVE 的 <code>ld1d</code> 各在什么场景下有效？</li></ol><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><p>1945 von Neumann 提出 stored-program concept；1965 Tomasulo 算法解决 float 指令依赖问题；1995 DEC Alpha 21264 是第一个 4-way superscalar OoO 的王者；2007 NVIDIA Tesla 用 unified shader model 开创 GPU 计算；2013 Google 发表 TPUv1 论文用 systolic array 做 inference；2016 Pascal P100 首次引入 HBM2；2022 Apple M1 Ultra 用 UltraFusion 把两芯片无缝接合；2023 Grace Hopper GH200 用 CXL 共享 CPU/GPU 内存。</p><hr><p>下一节 → <a href="./cpu-pipeline">CPU 流水线与指令级并行</a></p>`,14)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
